/// <summary>
/// Data contract task class for CSD transfer orders creation.
/// </summary>
[DataContract]
class METCreateCSDTransferOrderTaskContract
{
    private METFulfilmentProfileId profileId;
    private List salesLineList;
    private boolean canContinueFromStagingLane;

}

Method.Source:
/// <summary>
/// Gets and sets profile Id.
/// </summary>
/// <param name = "_profileId">Profile Id.</param>
/// <returns>Profile Id.</returns>
[DataMember, SysOperationControlVisibility(false)]
public METFulfilmentProfileId parmProfileId(METFulfilmentProfileId _profileId = profileId)
{
    profileId = _profileId;
    return profileId;
}

/// <summary>
/// Gets and sets SalesLine trans Ids list.
/// </summary>
/// <param name = "_salesLineList">SalesLine trans Ids list.</param>
/// <returns>SalesLine trans Ids list.</returns>
[DataMember, 
 SysOperationControlVisibility(false),
 AifCollectionType('_salesLineList', Types::String)]
public List parmSalesLineList(List _salesLineList = salesLineList)
{
    salesLineList = _salesLineList;
    return salesLineList;
}

/// <summary>
/// Parm method to get/set can continue from staging lane flag, which indicates whether to consider conitinus use of customer staging position fetched from Warehouse.
/// </summary>
/// <param name = "_canContinueFromStagingLane">Boolean value</param>
/// <returns>Boolean true represents continuous use of staging lane, false to use exiting value from Warehouse's Customer starting position</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public boolean parmContinueFromStagingLane(boolean _canContinueFromStagingLane = canContinueFromStagingLane)
{
    canContinueFromStagingLane = _canContinueFromStagingLane;
    return canContinueFromStagingLane;
}
